package io.floci.aws.services.cloudtrail;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.floci.aws.core.common.VendoredResources;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

/**
 * The S3 operations CloudTrail records as data events, read once from the vendored
 * {@code aws/cloudtrail-s3-data-events.json}: for each, the name its event is recorded under and whether it is
 * recorded read-only.
 *
 * <p>The file is generated by {@code tools/aws/regen_cloudtrail_s3_data_events.py} from botocore's S3 model, the S3
 * user guide's data events table for objects in general purpose buckets, which
 * {@code tools/aws/fetch_cloudtrail_s3_data_events.py} vendors, and AWS's S3 service reference. An operation is recorded
 * under its own name, the one the guide gives its call ({@code PutObjectRetention} as
 * {@code PutObjectLockRetention}), or the version-less one the guide lists for it ({@code ListObjectsV2} as
 * {@code ListObjects}), and is read-only when none of the actions it is authorized with changes anything. An
 * operation the file does not list is not a data event. {@code make aws-data-check} fails when it is stale.
 *
 * <p>A missing or malformed resource is a build defect, not a runtime condition, so loading fails with
 * {@link IllegalStateException}.
 */
public final class S3DataEvents {

    static final String RESOURCE_NAME = "aws/cloudtrail-s3-data-events.json";

    private static final ObjectMapper MAPPER = new ObjectMapper();

    /** The name CloudTrail records an S3 operation's data event under, and whether it records it read-only. */
    public record Event(String name, boolean readOnly) {
    }

    private static final class Holder {
        static final S3DataEvents EVENTS = VendoredResources.read(RESOURCE_NAME, "CloudTrail S3 data events",
                in -> new S3DataEvents(MAPPER.readTree(in)));
    }

    private final Map<String, Event> byOperation = new HashMap<>();
    private final Map<String, Boolean> readOnlyByName = new HashMap<>();

    S3DataEvents(JsonNode file) {
        JsonNode events = file.path("dataEvents");
        if (!events.isObject() || events.isEmpty()) {
            throw new IllegalStateException(RESOURCE_NAME + " carries no dataEvents");
        }
        events.properties().forEach(entry -> {
            JsonNode name = entry.getValue().path("eventName");
            JsonNode readOnly = entry.getValue().path("readOnly");
            if (!name.isTextual() || !readOnly.isBoolean()) {
                throw new IllegalStateException(RESOURCE_NAME + " gives " + entry.getKey()
                        + " no eventName or no readOnly flag");
            }
            Event event = new Event(name.asText(), readOnly.asBoolean());
            byOperation.put(entry.getKey(), event);
            Boolean recorded = readOnlyByName.putIfAbsent(event.name(), event.readOnly());
            if (recorded != null && recorded != event.readOnly()) {
                throw new IllegalStateException(RESOURCE_NAME + " records " + event.name()
                        + " both read-only and not");
            }
        });
    }

    /** The data event CloudTrail records the S3 operation as; empty for one it does not record as a data event. */
    public static Optional<Event> forOperation(String operation) {
        return operation == null ? Optional.empty() : Optional.ofNullable(Holder.EVENTS.byOperation.get(operation));
    }

    /** Whether CloudTrail records the S3 data event of the name read-only; false for a name the file does not list. */
    public static boolean isReadOnly(String eventName) {
        return Holder.EVENTS.readOnlyByName.getOrDefault(eventName, false);
    }
}
